SELECT , (SELECT COUNT(1) FROM api_test_cases c WHERE c.endpoint_id = e.id AND c.enabled = 1 AND c.assertions LIKE '%jsonPath%') AS strong_case_count, (SELECT COUNT(1) FROM api_test_cases c WHERE c.endpoint_id = e.id AND c.enabled = 1) AS enabled_case_count, (SELECT COUNT(1) FROM api_test_cases c WHERE c.endpoint_id = e.id) AS case_count FROM api_endpoints e
AND e.project IN #{pc}
AND e.status = #{status}
AND e.change_flag IS NOT NULL AND e.change_flag <> '' AND e.change_flag = #{changeFlag}
AND (e.path LIKE CONCAT('%', #{keyword}, '%') OR e.code_path LIKE CONCAT('%', #{keyword}, '%') OR e.handler LIKE CONCAT('%', #{keyword}, '%') OR e.summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY CASE WHEN e.status = 'DEPRECATED' THEN 0 WHEN e.change_flag IS NOT NULL AND e.change_flag <> '' THEN 1 ELSE 2 END, e.path

SELECT , 0 AS case_count
FROM api_endpoints e
WHERE e.http_method = #{httpMethod} AND e.path = #{path}

SELECT , 0 AS case_count
FROM api_endpoints e
WHERE e.project = #{project} AND e.http_method = #{httpMethod} AND e.path = #{path}

