code_path = #{codePath}, handler = #{handler}, source_file = #{sourceFile}, summary = #{summary}, status = #{status}, change_flag = #{changeFlag}, source_branch = #{sourceBranch}, change_note = #{changeNote}, fields_snapshot = #{fieldsSnapshot}, capture_meta = #{captureMeta}, doc_meta = #{docMeta}, tables_json = #{tablesJson}, last_synced_at = #{lastSyncedAt}, updated_at = NOW()
WHERE id = #{id}

